  "kind": "Read-only JSON data copy of already-existing immutable4569-byte builder invocation template, no new executable/runner/helper",
  "body": "$ErrorActionPreference = 'Stop'
$taskConfigPath = '__CONFIG_PATH__'
$taskConfigExpected = '__CONFIG_SHA256__'
if ((Get-FileHash -LiteralPath $taskConfigPath -Algorithm SHA256).Hash.ToLowerInvariant() -ne $taskConfigExpected) { throw 'configuration pin mismatch' }
$taskCfg = Get-Content -LiteralPath $taskConfigPath -Raw | ConvertFrom-Json
$taskSnapshotPath = $taskCfg.snapshot.path
if ((Get-FileHash -LiteralPath $taskSnapshotPath -Algorithm SHA256).Hash.ToLowerInvariant() -ne $taskCfg.snapshot.sha256) { throw 'snapshot pin mismatch' }
$taskSnapshot = Get-Content -LiteralPath $taskSnapshotPath -Raw | ConvertFrom-Json
foreach ($taskInput in $taskSnapshot.sources) {
 if ((Get-FileHash -LiteralPath $taskInput.path -Algorithm SHA256).Hash.ToLowerInvariant() -ne $taskInput.sha256) { throw ('source pin mismatch: ' + $taskInput.relativePath) }
}
if ((Get-FileHash -LiteralPath $taskCfg.guard.path -Algorithm SHA256).Hash.ToLowerInvariant() -ne $taskCfg.guard.sha256) { throw 'guard pin mismatch' }
foreach ($taskTool in $taskCfg.tools) { if ((Get-FileHash -LiteralPath $taskTool.path -Algorithm SHA256).Hash.ToLowerInvariant() -ne $taskTool.sha256) { throw 'builder tool pin mismatch' } }
foreach ($taskOutput in @($taskCfg.stdoutPath,$taskCfg.stderrPath,$taskCfg.outerPath)) { if (Test-Path -LiteralPath $taskOutput) { throw 'output already exists' } }
foreach ($taskArg in $taskCfg.args) { if ($taskArg -notmatch '^[A-Za-z0-9_+./:=,-]+$') { throw 'nonliteral bounded builder argument' } }
$taskInfo = New-Object System.Diagnostics.ProcessStartInfo
$taskInfo.FileName = $taskCfg.executable.path
$taskInfo.WorkingDirectory = $taskCfg.cwd
$taskInfo.Arguments = $taskCfg.args -join ' '
$taskInfo.UseShellExecute = $false
$taskInfo.CreateNoWindow = $true
$taskInfo.WindowStyle = [System.Diagnostics.ProcessWindowStyle]::Hidden
$taskInfo.RedirectStandardOutput = $true
$taskInfo.RedirectStandardError = $true
$taskInfo.EnvironmentVariables.Clear()
foreach ($taskEnv in $taskCfg.environment.PSObject.Properties) { $taskInfo.EnvironmentVariables[$taskEnv.Name] = [string]$taskEnv.Value }
$taskProc = New-Object System.Diagnostics.Process
$taskProc.StartInfo = $taskInfo
$taskClock = [System.Diagnostics.Stopwatch]::StartNew()
$taskExited = $false
$taskDisposed = $false
try {
 if (-not $taskProc.Start()) { throw 'builder did not start' }
 $taskPid = $taskProc.Id
 $taskStdout = $taskProc.StandardOutput.ReadToEndAsync()
 $taskStderr = $taskProc.StandardError.ReadToEndAsync()
 $taskProc.WaitForExit()
 $taskExited = $taskProc.HasExited
 $taskExit = $taskProc.ExitCode
 $taskOutText = $taskStdout.GetAwaiter().GetResult()
 $taskErrText = $taskStderr.GetAwaiter().GetResult()
} finally {
 $taskProc.Dispose()
 $taskDisposed = $true
 $taskClock.Stop()
}
$taskUtf8 = New-Object System.Text.UTF8Encoding($false)
foreach ($taskStream in @(@{path=$taskCfg.stdoutPath;text=$taskOutText},@{path=$taskCfg.stderrPath;text=$taskErrText})) {
 $taskFile = [System.IO.File]::Open($taskStream.path,[System.IO.FileMode]::CreateNew,[System.IO.FileAccess]::Write,[System.IO.FileShare]::None)
 try { $taskBytes = $taskUtf8.GetBytes($taskStream.text); $taskFile.Write($taskBytes,0,$taskBytes.Length) } finally { $taskFile.Dispose() }
}
$taskOuter = [ordered]@{owner='Root';exitCode=$taskExit;builderPid=$taskPid;kind=$taskCfg.kind;exited=$taskExited;disposed=$taskDisposed;elapsedMs=$taskClock.ElapsedMilliseconds;configPath=$taskConfigPath;uiOperated=$false;runtimeLaunched=$false;networkUsed=$false;productionBuildAccepted=$false;candidateAccepted=$false;goalComplete=$false}
$taskOuterJson = $taskOuter | ConvertTo-Json -Depth 4
$taskFile = [System.IO.File]::Open($taskCfg.outerPath,[System.IO.FileMode]::CreateNew,[System.IO.FileAccess]::Write,[System.IO.FileShare]::None)
try { $taskBytes = $taskUtf8.GetBytes($taskOuterJson + [Environment]::NewLine); $taskFile.Write($taskBytes,0,$taskBytes.Length) } finally { $taskFile.Dispose() }
foreach ($taskInput in $taskSnapshot.sources) {
 if ((Get-FileHash -LiteralPath $taskInput.path -Algorithm SHA256).Hash.ToLowerInvariant() -ne $taskInput.sha256) { throw ('post source pin mismatch: ' + $taskInput.relativePath) }
}
foreach ($taskTool in $taskCfg.tools) { if ((Get-FileHash -LiteralPath $taskTool.path -Algorithm SHA256).Hash.ToLowerInvariant() -ne $taskTool.sha256) { throw 'post builder tool pin mismatch' } }
$taskOuterJson
if ($taskOutText.Length -gt 0) { $taskOutText.Substring([Math]::Max(0,$taskOutText.Length-6500)) }
if ($taskErrText.Length -gt 0) { $taskErrText.Substring([Math]::Max(0,$taskErrText.Length-2200)) }
exit $taskExit",
